import { Component, h, Prop, ComponentInterface, Host, Element } from '@stencil/core';
import classnames from 'classnames';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { StatusDotSize, StatusDotVariant } from './types';

const prefix = 'status-dot';
/**
 * @slot default - Status label or custom content rendered next to the status dot.
 * @part self - The outer status dot wrapper.
 * @part mark - The mark element inside the component.
 * @part shape - The triangular mark used for `warning` and `error` variants.
 * @part dot - The circular mark used for the other variants.
 */
@Component({
  tag: 'ks-status-dot',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsStatusDot implements ComponentInterface {
  @Element() el!: HTMLKsStatusDotElement;
  /** Defines the visual variant of the status dot. */
  @Prop() variant: StatusDotVariant = 'inProgress';
  /** Specifies the size of the status dot. Can be either `"md"` or `"sm"`. */
  @Prop() size: StatusDotSize = 'md';

  constructor() {
    registerPluginManager(this.el);
  }

  private renderShape() {
    const width = this.size === 'md' ? '10' : '8';
    return (
      <svg
        part="mark shape"
        class={`${prefix}--shape`}
        xmlns="http://www.w3.org/2000/svg"
        width={width}
        height={width}
        fill="none"
      >
        <path
          d={
            this.size === 'md'
              ? // eslint-disable-next-line max-len
                'M3.611 1.568c.306-.53 1.071-.53 1.377 0l3.504 6.069c.306.53-.076 1.193-.689 1.193H.796c-.612 0-.995-.663-.689-1.193l3.504-6.069z'
              : 'M2.73 1.406a.6.6 0 0 1 1.041 0l2.648 4.587a.6.6 0 0 1-.52.901H.602a.6.6 0 0 1-.52-.901L2.73 1.406z'
          }
          fill="currentColor"
        />
      </svg>
    );
  }

  render() {
    return (
      <Host class="KsStatusDot" role="status">
        <div part="self" class={classnames(prefix, `${prefix}--${this.variant}`, `${prefix}--${this.size}`)}>
          {this.variant === 'warning' || this.variant === 'error' ? (
            this.renderShape()
          ) : (
            <div part="mark dot" class={`${prefix}--dot`}></div>
          )}
          <slot></slot>
        </div>
      </Host>
    );
  }
}
